import React, { useState, useMemo } from 'react';

interface Campaign {
  id: number;
  platform: string;
  campaign: string;
  ctr: number;
  cpc: number;
  roas: number;
  conversions: number;
  spend: number;
  status: string;
  benchmark: string;
  industry: string;
  impressions: number;
  cvr: number;
  cpa: number;
  revenue: number;
  roi: number;
}

interface CampaignTableProps {
  campaigns: Campaign[];
}

const CampaignTable: React.FC<CampaignTableProps> = ({ campaigns }) => {
  const [sortConfig, setSortConfig] = useState<{ key: string | null; direction: 'asc' | 'desc' }>({ key: null, direction: 'asc' });
  const [filterStatus, setFilterStatus] = useState('All');
  const [filterPlatform, setFilterPlatform] = useState('All');
  const [filterIndustry, setFilterIndustry] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');

  const platforms = Array.from(new Set(campaigns.map(campaign => campaign.platform)));
  const statuses = Array.from(new Set(campaigns.map(campaign => campaign.status)));
  const industries = Array.from(new Set(campaigns.map(campaign => campaign.industry)));

  const filteredAndSortedCampaigns = useMemo(() => {
    let filtered = campaigns.filter(campaign => {
      const matchesSearch = campaign.campaign.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           campaign.platform.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = filterStatus === 'All' || campaign.status === filterStatus;
      const matchesPlatform = filterPlatform === 'All' || campaign.platform === filterPlatform;
      const matchesIndustry = filterIndustry === 'All' || campaign.industry === filterIndustry;
      
      return matchesSearch && matchesStatus && matchesPlatform && matchesIndustry;
    });

    if (sortConfig.key) {
      filtered.sort((a, b) => {
        const aValue = (a as any)[sortConfig.key!];
        const bValue = (b as any)[sortConfig.key!];

        if (typeof aValue === 'string') {
          const aLower = aValue.toLowerCase();
          const bLower = bValue.toLowerCase();
          if (aLower < bLower) {
            return sortConfig.direction === 'asc' ? -1 : 1;
          }
          if (aLower > bLower) {
            return sortConfig.direction === 'asc' ? 1 : -1;
          }
          return 0;
        }

        if (aValue < bValue) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }

    return filtered;
  }, [campaigns, sortConfig, filterStatus, filterPlatform, filterIndustry, searchTerm]);

  const handleSort = (key: string) => {
    setSortConfig(prevConfig => ({
      key,
      direction: prevConfig.key === key && prevConfig.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const getStatusBadge = (status: string) => {
    const statusColors: { [key: string]: string } = {
      'Active': 'bg-green-500/20 text-green-400 border-green-500/30',
      'Scaling': 'bg-blue-500/20 text-blue-400 border-blue-500/30',
      'Paused': 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'
    };
    
    return (
      <span className={`px-3 py-1 rounded-full text-xs font-medium border ${statusColors[status] || 'bg-gray-500/20 text-gray-400 border-gray-500/30'}`}>
        {status}
      </span>
    );
  };

  const getIndustryBadge = (industry: string) => {
    const industryColors: { [key: string]: string } = {
      'EdTech': 'bg-purple-500/20 text-purple-400 border-purple-500/30',
      'E-commerce': 'bg-blue-500/20 text-blue-400 border-blue-500/30',
      'Q-commerce': 'bg-green-500/20 text-green-400 border-green-500/30'
    };
    
    return (
      <span className={`px-2 py-1 rounded-full text-xs font-medium border ${industryColors[industry] || 'bg-gray-500/20 text-gray-400 border-gray-500/30'}`}>
        {industry}
      </span>
    );
  };

  const getBenchmarkIndicator = (benchmark: string) => {
    const isAboveBenchmark = benchmark.includes('↗');
    return (
      <div className="flex items-center space-x-1">
        <span className={`text-xs ${isAboveBenchmark ? 'text-green-400' : 'text-red-400'}`}>
          {isAboveBenchmark ? '↗' : '↘'}
        </span>
        <span className={`text-xs ${isAboveBenchmark ? 'text-green-400' : 'text-red-400'}`}>
          {benchmark.replace('↗', '').replace('↘', '')}
        </span>
      </div>
    );
  };

  const formatCurrency = (value: number) => `₹${(value / 1000).toFixed(0)}K`;
  const formatNumber = (value: number) => value.toLocaleString();
  const formatPercentage = (value: number) => `${value.toFixed(1)}%`;

  return (
    <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border hover-lift">
      <div className="mb-6">
        <h3 className="text-xl font-bold text-dark-text mb-4">Campaign Performance Table</h3>
        
        {/* Filters */}
        <div className="flex flex-wrap gap-4 mb-4">
          <div className="flex-1 min-w-64">
            <input
              type="text"
              placeholder="Search campaigns..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-dark-text placeholder-dark-text-secondary focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          
          <select
            value={filterPlatform}
            onChange={(e) => setFilterPlatform(e.target.value)}
            className="px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-dark-text focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="All">All Platforms</option>
            {platforms.map(platform => (
              <option key={platform} value={platform}>{platform}</option>
            ))}
          </select>
          
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-dark-text focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="All">All Status</option>
            {statuses.map(status => (
              <option key={status} value={status}>{status}</option>
            ))}
          </select>

          <select
            value={filterIndustry}
            onChange={(e) => setFilterIndustry(e.target.value)}
            className="px-4 py-2 bg-dark-bg border border-dark-border rounded-lg text-dark-text focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="All">All Industries</option>
            {industries.map(industry => (
              <option key={industry} value={industry}>{industry}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b border-dark-border">
              <th 
                className="text-left py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('platform')}
              >
                Platform {sortConfig.key === 'platform' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th 
                className="text-left py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('campaign')}
              >
                Campaign {sortConfig.key === 'campaign' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th 
                className="text-right py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('ctr')}
              >
                CTR {sortConfig.key === 'ctr' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th 
                className="text-right py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('cpc')}
              >
                CPC {sortConfig.key === 'cpc' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th 
                className="text-right py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('roas')}
              >
                ROAS {sortConfig.key === 'roas' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th 
                className="text-right py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('conversions')}
              >
                Conversions {sortConfig.key === 'conversions' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th 
                className="text-right py-3 px-4 text-dark-text-secondary font-medium cursor-pointer hover:text-dark-text transition-colors"
                onClick={() => handleSort('spend')}
              >
                Spend {sortConfig.key === 'spend' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
              </th>
              <th className="text-center py-3 px-4 text-dark-text-secondary font-medium">Status</th>
              <th className="text-center py-3 px-4 text-dark-text-secondary font-medium">Industry</th>
              <th className="text-center py-3 px-4 text-dark-text-secondary font-medium">Benchmark</th>
            </tr>
          </thead>
          <tbody>
            {filteredAndSortedCampaigns.map((campaign) => (
              <tr 
                key={campaign.id} 
                className="border-b border-dark-border hover:bg-dark-bg/50 transition-colors"
              >
                <td className="py-4 px-4 text-dark-text font-medium">{campaign.platform}</td>
                <td className="py-4 px-4 text-dark-text">{campaign.campaign}</td>
                <td className="py-4 px-4 text-right text-dark-text">{formatPercentage(campaign.ctr)}</td>
                <td className="py-4 px-4 text-right text-dark-text">{formatCurrency(campaign.cpc)}</td>
                <td className="py-4 px-4 text-right text-dark-text font-medium">{campaign.roas.toFixed(1)}x</td>
                <td className="py-4 px-4 text-right text-dark-text">{formatNumber(campaign.conversions)}</td>
                <td className="py-4 px-4 text-right text-dark-text">{formatCurrency(campaign.spend)}</td>
                <td className="py-4 px-4 text-center">{getStatusBadge(campaign.status)}</td>
                <td className="py-4 px-4 text-center">{getIndustryBadge(campaign.industry)}</td>
                <td className="py-4 px-4 text-center">{getBenchmarkIndicator(campaign.benchmark)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Summary */}
      <div className="mt-6 pt-4 border-t border-dark-border">
        <div className="flex justify-between items-center text-sm text-dark-text-secondary">
          <span>Showing {filteredAndSortedCampaigns.length} of {campaigns.length} campaigns</span>
          <span>Total Spend: {formatCurrency(campaigns.reduce((sum, c) => sum + c.spend, 0))}</span>
        </div>
      </div>
    </div>
  );
};

export default CampaignTable;
