function App() {
  const [data, setData] = useState<CampaignData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      try {
        // Try to load from JSON first
        const response = await fetch('/data.json');
        if (response.ok) {
          const jsonData = await response.json();
          setData(jsonData);
        } else {
          // Fallback to embedded data
          setData(fallbackData);
        }
      } catch (err) {
        // Fallback to embedded data on error
        console.log('Using fallback data due to error:', err);
        setData(fallbackData);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-dark-bg flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-dark-text text-xl">Loading Performance Marketing Dashboard...</p>
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="min-h-screen bg-dark-bg flex items-center justify-center">
        <div className="text-center">
          <div className="text-gray-500 text-6xl mb-4">📊</div>
          <p className="text-dark-text text-xl">No data available</p>
        </div>
      </div>
    );
  }

  return (
    <div className="App">
      <Dashboard 
        campaigns={data.campaigns}
        summaryMetrics={data.summaryMetrics}
        conversionTrends={data.conversionTrends}
        platformBenchmarks={data.platformBenchmarks}
        industryBenchmarks={data.industryBenchmarks}
        platformInsights={data.platformInsights}
      />
    </div>
  );
}

export default App;