import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar, Line, Pie } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

interface ChartsProps {
  campaigns: any[];
  conversionTrends: any[];
}

const Charts: React.FC<ChartsProps> = ({ campaigns, conversionTrends }) => {
  // Process campaigns data for charts
  const platformData = campaigns.reduce((acc: any, campaign: any) => {
    if (!acc[campaign.platform]) {
      acc[campaign.platform] = {
        platform: campaign.platform,
        spend: 0,
        roas: 0,
        count: 0
      };
    }
    acc[campaign.platform].spend += campaign.spend;
    acc[campaign.platform].roas += campaign.roas;
    acc[campaign.platform].count += 1;
    return acc;
  }, {});

  const chartData = Object.values(platformData).map((item: any) => ({
    platform: item.platform,
    spend: item.spend,
    roas: item.roas / item.count // Average ROAS
  }));

  // Bar Chart Data - Spend vs ROAS by Platform
  const barChartData = {
    labels: chartData.map(item => item.platform),
    datasets: [
      {
        label: 'Spend (₹)',
        data: chartData.map(item => item.spend),
        backgroundColor: 'rgba(66, 133, 244, 0.8)',
        borderColor: 'rgba(66, 133, 244, 1)',
        borderWidth: 2,
        borderRadius: 8,
        borderSkipped: false,
      },
      {
        label: 'ROAS (x)',
        data: chartData.map(item => item.roas * 10000), // Scale for visibility
        backgroundColor: 'rgba(52, 168, 83, 0.8)',
        borderColor: 'rgba(52, 168, 83, 1)',
        borderWidth: 2,
        borderRadius: 8,
        borderSkipped: false,
      },
    ],
  };

  const barChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top' as const,
        labels: {
          color: '#F1F5F9',
          font: {
            size: 12,
          },
        },
      },
      title: {
        display: true,
        text: 'Spend vs ROAS by Platform',
        color: '#F1F5F9',
        font: {
          size: 16,
        },
      },
      tooltip: {
        callbacks: {
          label: function(context: any) {
            if (context.datasetIndex === 0) {
              return `Spend: ₹${(context.parsed.y / 1000).toFixed(0)}K`;
            } else {
              return `ROAS: ${(context.parsed.y / 10000).toFixed(1)}x`;
            }
          }
        }
      }
    },
    scales: {
      x: {
        ticks: {
          color: '#94A3B8',
        },
        grid: {
          color: 'rgba(51, 65, 85, 0.5)',
        },
      },
      y: {
        ticks: {
          color: '#94A3B8',
          callback: function(value: any) {
            return `₹${(value / 1000).toFixed(0)}K`;
          }
        },
        grid: {
          color: 'rgba(51, 65, 85, 0.5)',
        },
        title: {
          display: true,
          text: 'Spend (₹)',
          color: '#F1F5F9',
        }
      },
      y1: {
        type: 'linear' as const,
        position: 'right' as const,
        grid: {
          drawOnChartArea: false,
        },
        ticks: {
          color: '#94A3B8',
          callback: function(value: any) {
            return `${(value / 10000).toFixed(1)}x`;
          }
        },
        title: {
          display: true,
          text: 'ROAS (x)',
          color: '#F1F5F9',
        }
      },
    },
  };

  // Line Chart Data - Conversion Trends Over Time
  const lineChartData = {
    labels: conversionTrends.map(item => item.month),
    datasets: [
      {
        label: 'Conversions',
        data: conversionTrends.map(item => item.conversions),
        fill: false,
        borderColor: 'rgb(251, 188, 4)',
        backgroundColor: 'rgba(251, 188, 4, 0.1)',
        tension: 0.1,
        pointBackgroundColor: 'rgb(251, 188, 4)',
        pointBorderColor: '#fff',
        pointHoverBackgroundColor: '#fff',
        pointHoverBorderColor: 'rgb(251, 188, 4)',
      },
    ],
  };

  const lineChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top' as const,
        labels: {
          color: '#F1F5F9',
          font: {
            size: 12,
          },
        },
      },
      title: {
        display: true,
        text: 'Conversion Trends Over Time',
        color: '#F1F5F9',
        font: {
          size: 16,
        },
      },
      tooltip: {
        callbacks: {
          label: function(context: any) {
            if (context.datasetIndex === 0) {
              return `Conversions: ${context.parsed.y}`;
            } else {
              return `Revenue: ₹${context.parsed.y}L`;
            }
          }
        }
      }
    },
    scales: {
      x: {
        ticks: {
          color: '#94A3B8',
        },
        grid: {
          color: 'rgba(51, 65, 85, 0.5)',
        },
      },
      y: {
        ticks: {
          color: '#94A3B8',
          callback: function(value: any) {
            return `${value}K`;
          }
        },
        grid: {
          color: 'rgba(51, 65, 85, 0.5)',
        },
        title: {
          display: true,
          text: 'Conversions',
          color: '#F1F5F9',
        }
      },
    },
  };

  // Pie Chart Data - Spend Share by Platform
  const pieChartData = {
    labels: chartData.map(item => item.platform),
    datasets: [
      {
        data: chartData.map(item => item.spend),
        backgroundColor: [
          '#4285F4', // Google Blue
          '#34A853', // Google Green
          '#FBBC04', // Google Yellow
          '#EA4335', // Google Red
          '#8B5CF6', // Violet
          '#EC4899', // Pink
          '#10B981', // Emerald
          '#EF4444', // Red
          '#3B82F6', // Blue
          '#F97316', // Orange
          '#6B7280', // Gray
          '#D946EF', // Fuchsia
        ],
        borderColor: '#0F172A',
        borderWidth: 2,
        hoverOffset: 4,
      },
    ],
  };

  const pieChartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'right' as const,
        labels: {
          color: '#F1F5F9',
          font: {
            size: 12,
          },
          padding: 20,
          usePointStyle: true,
          pointStyle: 'circle',
        },
      },
      title: {
        display: true,
        text: 'Spend Share by Platform',
        color: '#F1F5F9',
        font: {
          size: 16,
        },
      },
      tooltip: {
        callbacks: {
          label: function(context: any) {
            const total = context.dataset.data.reduce((a: number, b: number) => a + b, 0);
            const percentage = ((context.parsed / total) * 100).toFixed(1);
            return `${context.label}: ₹${(context.parsed / 1000).toFixed(0)}K (${percentage}%)`;
          }
        }
      }
    },
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Bar Chart */}
      <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border hover-lift">
        <div className="h-96">
          <Bar data={barChartData} options={barChartOptions} />
        </div>
      </div>

      {/* Line Chart */}
      <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border hover-lift">
        <div className="h-96">
          <Line data={lineChartData} options={lineChartOptions} />
        </div>
      </div>

      {/* Pie Chart */}
      <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border hover-lift lg:col-span-2">
        <div className="h-96">
          <Pie data={pieChartData} options={pieChartOptions} />
        </div>
      </div>
    </div>
  );
};

export default Charts;