import React, { useState } from 'react';

interface DashboardInsightsProps {
  platformInsights: any;
  industryBenchmarks: any;
}

const DashboardInsights: React.FC<DashboardInsightsProps> = ({ platformInsights, industryBenchmarks }) => {
  const [expandedSections, setExpandedSections] = useState({
    platform: true,
    industry: false,
    benchmarks: false
  });

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev[section as keyof typeof prev]
    }));
  };

  return (
    <div className="space-y-6">
      {/* Platform Insights */}
      <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border">
        <button
          className="flex justify-between items-center w-full text-xl font-semibold text-dark-text py-2 focus:outline-none"
          onClick={() => toggleSection('platform')}
        >
          Platform Performance Insights
          <span className="text-2xl">{expandedSections.platform ? '−' : '+'}</span>
        </button>
        
        {expandedSections.platform && (
          <div className="mt-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 animate-fade-in">
            {Object.entries(platformInsights).map(([platform, insights]: [string, any], index) => (
              <div key={index} className="bg-dark-bg/50 rounded-lg p-4 border border-dark-border">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="text-lg font-semibold text-dark-text">{platform}</h4>
                </div>
                
                <div className="space-y-3">
                  <div>
                    <p className="text-sm text-dark-text-secondary mb-2">
                      <span className="font-medium text-blue-400">Performance Tip:</span> {insights.tip}
                    </p>
                    <p className="text-sm text-dark-text-secondary">
                      <span className="font-medium text-green-400">Recommendation:</span> {insights.recommendation}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Industry Benchmarks */}
      <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border">
        <button
          className="flex justify-between items-center w-full text-xl font-semibold text-dark-text py-2 focus:outline-none"
          onClick={() => toggleSection('industry')}
        >
          Industry Benchmarks
          <span className="text-2xl">{expandedSections.industry ? '−' : '+'}</span>
        </button>
        
        {expandedSections.industry && (
          <div className="mt-6 grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
            {Object.entries(industryBenchmarks).map(([industry, benchmarks]: [string, any], index) => (
              <div key={index} className="bg-dark-bg/50 rounded-lg p-4 border border-dark-border">
                <h4 className="text-lg font-semibold text-dark-text mb-3">{industry}</h4>
                <div className="space-y-2">
                  {Object.entries(benchmarks).map(([brand, metrics]: [string, any]) => (
                    <div key={brand} className="border-l-2 border-blue-500 pl-3">
                      <h5 className="font-medium text-dark-text">{brand}</h5>
                      <div className="text-sm text-dark-text-secondary">
                        {Object.entries(metrics).map(([metric, value]: [string, any]) => (
                          <div key={metric}>
                            <span className="font-medium">{metric}:</span> {value}
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Performance Summary */}
      <div className="bg-dark-card rounded-xl p-6 shadow-lg border border-dark-border">
        <h3 className="text-xl font-semibold text-dark-text mb-4">Key Performance Highlights</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="bg-gradient-to-r from-blue-500/20 to-blue-600/20 rounded-lg p-4 border border-blue-500/30">
            <div className="text-blue-400 text-sm font-medium mb-1">Top Performing Channel</div>
            <div className="text-dark-text font-semibold">Email Automation</div>
            <div className="text-dark-text-secondary text-sm">25.0x ROAS</div>
          </div>
          <div className="bg-gradient-to-r from-green-500/20 to-green-600/20 rounded-lg p-4 border border-green-500/30">
            <div className="text-green-400 text-sm font-medium mb-1">Highest CTR</div>
            <div className="text-dark-text font-semibold">Swiggy Instamart</div>
            <div className="text-dark-text-secondary text-sm">6.0% CTR</div>
          </div>
          <div className="bg-gradient-to-r from-purple-500/20 to-purple-600/20 rounded-lg p-4 border border-purple-500/30">
            <div className="text-purple-400 text-sm font-medium mb-1">Best Conversion Rate</div>
            <div className="text-dark-text font-semibold">WhatsApp Automation</div>
            <div className="text-dark-text-secondary text-sm">15.0% CVR</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DashboardInsights;