import React, { useState, useEffect } from 'react';
import CountUp from 'react-countup';

interface Metrics {
  totalSpend: number;
  totalConversions: number;
  totalImpressions: number;
  totalClicks: number;
  totalRevenue: number;
  averageCTR: number;
  averageROAS: number;
  averageCPA: number;
  averageCPC: number;
  averageROI: number;
}

interface KpiCardsProps {
  metrics: Metrics;
}

const KpiCards: React.FC<KpiCardsProps> = ({ metrics }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const kpiData = [
    {
      title: 'Total Impressions',
      value: metrics.totalImpressions,
      format: (value: number) => `${(value / 100000).toFixed(1)}L`,
      icon: '👁️',
      color: 'from-blue-500 to-blue-600',
      hoverColor: 'hover:from-blue-400 hover:to-blue-500',
      description: 'Total reach across all campaigns'
    },
    {
      title: 'Total Clicks',
      value: metrics.totalClicks,
      format: (value: number) => `${(value / 1000).toFixed(1)}K`,
      icon: '🖱️',
      color: 'from-green-500 to-green-600',
      hoverColor: 'hover:from-green-400 hover:to-green-500',
      description: 'Total clicks generated'
    },
    {
      title: 'Average CTR',
      value: metrics.averageCTR,
      format: (value: number) => `${value.toFixed(1)}%`,
      icon: '📊',
      color: 'from-purple-500 to-purple-600',
      hoverColor: 'hover:from-purple-400 hover:to-purple-500',
      description: 'Click-through rate'
    },
    {
      title: 'Total Conversions',
      value: metrics.totalConversions,
      format: (value: number) => `${(value / 1000).toFixed(1)}K`,
      icon: '🎯',
      color: 'from-orange-500 to-orange-600',
      hoverColor: 'hover:from-orange-400 hover:to-orange-500',
      description: 'Total leads generated'
    },
    {
      title: 'Average ROAS',
      value: metrics.averageROAS,
      format: (value: number) => `${value.toFixed(1)}x`,
      icon: '💰',
      color: 'from-red-500 to-red-600',
      hoverColor: 'hover:from-red-400 hover:to-red-500',
      description: 'Return on ad spend'
    },
    {
      title: 'Total Spend',
      value: metrics.totalSpend,
      format: (value: number) => `₹${(value / 100000).toFixed(1)}L`,
      icon: '💸',
      color: 'from-indigo-500 to-indigo-600',
      hoverColor: 'hover:from-indigo-400 hover:to-indigo-500',
      description: 'Total advertising investment'
    }
  ];

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
      {kpiData.map((kpi, index) => (
        <div
          key={kpi.title}
          className={`bg-gradient-to-r ${kpi.color} ${kpi.hoverColor} rounded-xl p-6 shadow-lg transform transition-all duration-300 hover:scale-105 hover:shadow-xl animate-slide-up hover-lift`}
          style={{ animationDelay: `${index * 0.1}s` }}
        >
          <div className="flex items-center justify-between mb-4">
            <div className="text-4xl opacity-80">
              {kpi.icon}
            </div>
            <div className="w-2 h-2 bg-white rounded-full animate-pulse-slow"></div>
          </div>
          
          <div className="mb-2">
            <p className="text-white/80 text-sm font-medium">{kpi.title}</p>
            <div className="text-3xl font-bold text-white">
              {isVisible && (
                <CountUp
                  start={0}
                  end={kpi.value}
                  duration={2.5}
                  formattingFn={kpi.format}
                  useEasing={true}
                  separator=","
                />
              )}
            </div>
          </div>
          
          <div className="mt-4">
            <p className="text-white/70 text-xs">{kpi.description}</p>
          </div>
        </div>
      ))}
    </div>
  );
};

export default KpiCards;
